// Analyzes link density across vault
const files = app.vault.getMarkdownFiles();
const linkCounts = files.map(file => {
  const cache = app.metadataCache.getFileCache(file);
  const links = cache?.links?.length || 0;
  return { path: file.path, links };
});

const avgLinks = linkCounts.reduce((sum, f) => sum + f.links, 0) / files.length;
const isolated = linkCounts.filter(f => f.links < 3);

console.log(`Average links per note: ${avgLinks.toFixed(2)}`);
console.log(`Isolated notes: ${isolated.length}`);
